import numpy as np

def process_video_frames(frame_prev: np.ndarray, frame_curr: np.ndarray) -> np.ndarray:
    # Selisih absolut antar-frame
    diff = np.abs(frame_curr.astype(np.float32) - frame_prev.astype(np.float32))
    return np.clip(diff, 0, 255).astype(np.uint8)

import numpy as np

def evaluate_video_metric(ground_truth: np.ndarray, estimated: np.ndarray) -> float:
    # Peak Signal-to-Noise Ratio (PSNR)
    mse = np.mean((ground_truth.astype(np.float32) - estimated.astype(np.float32)) ** 2)
    if mse < 1e-6:
        return 100.0
    return float(10 * np.log10((255.0 ** 2) / mse))
